        if (持有物品[hk] === false || 持有物品[hk] == null) { continue; }
        持有键.push(String(hk).trim());
    }
}
function 持有(x) {
    if (x == null) {
        return false;
    }
    var arr = Array.isArray(x) ? x : [x];
    for (var a = 0; a < arr.length; a++) {
        var want = String(arr[a]).trim();
        if (!want) { continue; }
        for (var b = 0; b < 持有键.length; b++) {
