    if (x == null) {
        return false;
    }
    var arr = Array.isArray(x) ? x : [x];
    for (var i = 0; i < arr.length; i++) {
        if (已完成键[String(arr[i]).trim()]) {
            return true;
        }
    }
    return false;
}
