    { entry: '后剧情条目/地虫异变', when: '立下誓约的那一天', note: '完成「立下誓约的那一天」事件后' },
    { entry: '后剧情条目/以太多面体', holds: ['完合的正四面体·缺遗', '无限的正六面体·界域', '无序的正八面体·均和', '真理的正十二面体·幻梦', '平止的正二十面体·悸动'], note: '持有任一以太多面体时' },
