    } catch(e) {
        形 = '';
    }
    if (七罪角色.indexOf(name) !== -1) {
        activated.push('角色/' + name + '/变身阶段/' + (形 === '解放' ? '解放' : '日常'));
    } else if (阶段覆盖[name]) {
        var 覆 = 阶段覆盖[name];
        activated.push('角色/' + name + '/变身阶段/' + (已完成键[覆.事件] ? 覆.已完成 : 覆.未完成));
